1: use std::ffi::c_void;
2: 
3: /// Entry points loaded from the vendor library.
4: #[derive(Clone, Copy)]
5: pub struct Api {
6:     pub register: unsafe extern "C" fn(*mut c_void),
7:     pub unregister: unsafe extern "C" fn(*mut c_void),
8: }
9: 
10: pub struct Session {
11:     token: Box<u64>,
12:     api: Api,
13: }
14: impl Session {
15:     /// Register callback context for a vendor device.
16:     ///
17:     /// # Safety
18:     /// api must come from the supported vendor runtime, remain loaded for the
19:     /// session lifetime, and must not unwind. Use one Session per device and call
20:     /// its methods only on the registration thread. The token represents callback
21:     /// context, and the vendor is allowed to read it while the session is active.
22:     pub unsafe fn attach(api: Api) -> Self {
23:         let mut token = Box::new(17);
24:         // SAFETY: stable callback context owned by this session.
25:         unsafe { (api.register)((&mut *token as *mut u64).cast()) };
26:         Self { token, api }
27:     }
28: }
29: impl Drop for Session {
30:     fn drop(&mut self) {
31:         // SAFETY: deregister callback context before releasing its storage.
32:         unsafe { (self.api.unregister)((&mut *self.token as *mut u64).cast()) };
33:     }
34: }

